package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.std.NumberSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class NumberSerializer_acceptJsonFormatVisitor_TriageGen2Test {

    @Test
    public void testAcceptJsonFormatVisitor_IsInt_True() throws JsonMappingException {
        // Given: A serializer where _isInt is true
        // Since _isInt is private, we must use a subclass or a specific type that sets it.
        // In Jackson's NumberSerializer, _isInt is set via the constructor/internal logic.
        // For testing purposes, we mock/spy to trigger the first branch.
        NumberSerializer serializer = spy(new NumberSerializer(Integer.class));
        // We force the _isInt field behavior by mocking the method if possible, 
        // but since we want to test the actual code logic, we use the constructor that sets _isInt.
        // However, NumberSerializer's _isInt is protected/private. 
        // Based on the provided code snippet, we assume we can trigger the branch.

        // To strictly follow the provided code logic for coverage:
        // We need to find a type that results in _isInt = true.
        NumberSerializer intSerializer = new NumberSerializer(Integer.class);
        // Note: In actual Jackson, Integer.class sets _isInt = true.

        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // When
        intSerializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Then
        // visitIntFormat is called internally which calls visitor.expectNumberFormat(typeHint, JsonParser.NumberType.BIG_INTEGER)
        verify(visitor).expectNumberFormat(typeHint, JsonParser.NumberType.BIG_INTEGER);
    }

    @Test
    public void testAcceptJsonFormatVisitor_IsNotInt_IsBigDecimal() throws JsonMappingException {
        // Given: A serializer where _isInt is false and handledType is BigDecimal
        NumberSerializer serializer = new NumberSerializer(BigDecimal.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // When
        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Then
        // visitFloatFormat is called which calls visitor.expectNumberFormat(typeHint, JsonParser.NumberType.BIG_INTEGER)
        verify(visitor).expectNumberFormat(typeHint, JsonParser.NumberType.BIG_INTEGER);
    }

    @Test
    public void testAcceptJsonFormatVisitor_IsNotInt_NotBigDecimal() throws JsonMappingException {
        // Given: A serializer where _isInt is false and handledType is Double
        NumberSerializer serializer = new NumberSerializer(Double.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // When
        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Then
        // The 'else' branch is taken: visitor.expectNumberFormat(typeHint)
        verify(visitor).expectNumberFormat(typeHint);
        // Verify that the BIG_INTEGER version was NOT called
        verify(visitor, never()).expectNumberFormat(eq(typeHint), any(JsonParser.NumberType.class));
    }

    @Test(expected = JsonMappingException.class)
    public void testAcceptJsonFormatVisitor_ThrowsException() throws JsonMappingException {
        // Given
        NumberSerializer serializer = new NumberSerializer(Double.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // Simulate exception
        doThrow(new JsonMappingException(null, "Error")).when(visitor).expectNumberFormat(any());

        // When
        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Then - Exception expected
    }
}
